<?php
require_once __DIR__ . '/bootstrap.php';
require_method('POST');
$actor=require_roles('adviser');
$input=json_decode((string)file_get_contents('php://input'),true)?:[];
$transactionId=(int)($input['transaction_id']??0);$amountDue=round((float)($input['amount_due']??0),2);$reason=trim((string)($input['reason']??''));
if($transactionId<=0||$amountDue<0||$reason===''||strlen($reason)>500)api_error(400,'Transaction, non-negative amount due, and correction reason are required.','INVALID_CORRECTION');
try{$pdo=db();$pdo->beginTransaction();$stmt=$pdo->prepare('SELECT t.user_id,t.amount_due,COALESCE(SUM(CASE WHEN p.is_voided=0 THEN p.amount ELSE 0 END),0) paid FROM transactions t JOIN requirements r ON r.requirement_id=t.requirement_id LEFT JOIN transaction_payments p ON p.transaction_id=t.transaction_id WHERE t.transaction_id=? AND r.club_id=? GROUP BY t.transaction_id,t.user_id,t.amount_due FOR UPDATE');$stmt->execute([$transactionId,$actor['club_id']]);$tx=$stmt->fetch(PDO::FETCH_ASSOC);if(!$tx){$pdo->rollBack();api_error(404,'Transaction was not found in this club.','TRANSACTION_NOT_FOUND');}if($amountDue<(float)$tx['paid']){$pdo->rollBack();api_error(409,'Amount due cannot be lower than recorded payments.','AMOUNT_BELOW_PAID');}$pdo->prepare('UPDATE transactions SET amount_due=? WHERE transaction_id=?')->execute([$amountDue,$transactionId]);$totals=refresh_transaction_totals($pdo,$transactionId);audit_event($pdo,$actor,'transaction_corrected','transaction',$transactionId,(int)$tx['user_id'],['previous_amount_due'=>(float)$tx['amount_due'],'amount_due'=>$amountDue,'reason'=>$reason]);$pdo->commit();echo json_encode(['success'=>true]+$totals);}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();error_log('IMSCCA transaction correction failure: '.$e->getMessage());api_error(500,'The transaction could not be corrected.','SERVER_ERROR');}
